parameters.jsCode:
const body = $input.first().json.body;
const required = ['source_content', 'source_type'];
const missing = required.filter(f => !body[f]);
if (missing.length) return [{ json: { valid: false, error: `Missing: ${missing.join(', ')}` } }];
if (body.source_content.trim().length < 100) return [{ json: { valid: false, error: 'source_content too short' } }];

const sourceTypes = ['blog_post', 'podcast_transcript', 'video_transcript', 'newsletter', 'webinar_notes', 'research_report', 'interview', 'thread', 'other'];
const sourceType = sourceTypes.includes(body.source_type) ? body.source_type : 'other';

const allFormats = ['linkedin_post', 'twitter_thread', 'email_newsletter', 'instagram_caption', 'youtube_description', 'tiktok_script', 'pull_quotes', 'key_takeaways', 'faq'];
const requestedFormats = Array.isArray(body.target_formats)
  ? body.target_formats.filter(f => allFormats.includes(f))
  : allFormats.slice(0, 4);

return [{
  json: {
    valid: true,
    sourceContent: body.source_content.trim().slice(0, 8000),
    sourceType,
    sourceTitle: body.source_title || '',
    sourceAuthor: body.source_author || '',
    targetFormats: requestedFormats,
    brand: (body.brand_voice || '').slice(0, 400),
    targetAudience: body.target_audience || '',
    includeEmojis: body.include_emojis !== false,
    replyEmail: body.reply_email || null,
    requestedAt: new Date().toISOString()
  }
}];

values.content:
Repurpose this content into the requested formats.

Source type: {{ $json.sourceType }}
Title: {{ $json.sourceTitle || 'untitled' }}
Author: {{ $json.sourceAuthor || 'not specified' }}
Target audience: {{ $json.targetAudience || 'general professional' }}
Brand voice notes: {{ $json.brand || 'none — use tone from source' }}
Include emojis: {{ $json.includeEmojis }}
Formats requested: {{ $json.targetFormats.join(', ') }}

Source content:
{{ $json.sourceContent }}

Return this JSON:
{
  "content_summary": "2 sentences on what this content is about and its strongest angle",
  "best_performing_angle": "the single most shareable/engaging idea in this content — be specific",
  "formats": {
    "linkedin_post": "full post text or null if not requested",
    "twitter_thread": ["tweet 1", "tweet 2"] or null,
    "email_newsletter": { "subject": "...", "body": "..." } or null,
    "instagram_caption": "full caption with hashtags or null",
    "youtube_description": "full description or null",
    "tiktok_script": "full spoken script or null",
    "pull_quotes": ["quote 1", "quote 2"] or null,
    "key_takeaways": ["takeaway 1"] or null,
    "faq": [{ "q": "question", "a": "answer" }] or null
  }
}

parameters.jsCode:
const raw = $input.first().json.text || $input.first().json.content?.[0]?.text || '';
let repurposed;
try {
  repurposed = JSON.parse(raw.replace(/```json|```/g,'').trim());
} catch(e) {
  return [{ json: { error: 'Parse error', raw } }];
}
const input = $('Validate Input').first().json;
repurposed._meta = { sourceTitle: input.sourceTitle, sourceType: input.sourceType, targetFormats: input.targetFormats, replyEmail: input.replyEmail };
return [{ json: repurposed }];

const r = $input.first().json;
const m = r._meta;
function esc(s) { return String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }

const formatLabel = { linkedin_post:'LinkedIn Post', twitter_thread:'Twitter/X Thread', email_newsletter:'Email Newsletter', instagram_caption:'Instagram Caption', youtube_description:'YouTube Description', tiktok_script:'TikTok Script', pull_quotes:'Pull Quotes', key_takeaways:'Key Takeaways', faq:'FAQ' };
const formatIcon = { linkedin_post:'💼', twitter_thread:'🐦', email_newsletter:'📧', instagram_caption:'📸', youtube_description:'▶️', tiktok_script:'🎵', pull_quotes:'💬', key_takeaways:'✅', faq:'❓' };

const formatBlocks = (m.targetFormats || []).map(fmt => {
  const content = r.formats?.[fmt];
  if (!content) return '';

  let rendered = '';
  if (fmt === 'twitter_thread' && Array.isArray(content)) {
    rendered = content.map((t,i) => `<div style="font-size:14px;padding:8px 0;border-bottom:1px solid #f0f0f0;line-height:1.6">${esc(t)}</div>`).join('');
  } else if (fmt === 'email_newsletter' && typeof content === 'object') {
    rendered = `<div style="font-size:12px;color:#9ca3af;margin-bottom:4px">Subject: <strong>${esc(content.subject)}</strong></div><div style="font-size:14px;line-height:1.75;white-space:pre-wrap">${esc(content.body)}</div>`;
  } else if (fmt === 'pull_quotes' && Array.isArray(content)) {
    rendered = content.map(q => `<div style="border-left:3px solid #6366f1;padding:10px 14px;background:#f5f3ff;border-radius:0 6px 6px 0;margin-bottom:8px;font-size:14px;font-style:italic;line-height:1.6">${esc(q)}</div>`).join('');
  } else if (fmt === 'key_takeaways' && Array.isArray(content)) {
    rendered = `<ul style="padding-left:18px;margin:0">${content.map(t => `<li style="font-size:14px;margin-bottom:7px;line-height:1.55">${esc(t)}</li>`).join('')}</ul>`;
  } else if (fmt === 'faq' && Array.isArray(content)) {
    rendered = content.map(qa => `<div style="margin-bottom:12px"><div style="font-size:14px;font-weight:600;color:#111;margin-bottom:3px">Q: ${esc(qa.q)}</div><div style="font-size:14px;color:#555;line-height:1.6">A: ${esc(qa.a)}</div></div>`).join('');
  } else {
    rendered = `<div style="font-size:14px;line-height:1.75;white-space:pre-wrap">${esc(String(content))}</div>`;
  }

  return `<div style="background:#fff;padding:18px 26px;border:1px solid #e5e7eb;border-top:3px solid #f3f4f6;margin-top:0">
    <div style="font-size:12px;font-weight:700;text-transform:uppercase;letter-spacing:0.5px;color:#9ca3af;margin-bottom:10px">${formatIcon[fmt]||''} ${formatLabel[fmt]||fmt}</div>
    ${rendered}
  </div>`;
}).join('');

const html = `<!DOCTYPE html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head>
<body style="margin:0;padding:16px;background:#f9fafb;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;color:#111">
<div style="max-width:680px;margin:0 auto">
  <div style="background:#111827;color:#fff;padding:20px 26px;border-radius:10px 10px 0 0">
    <div style="font-size:11px;text-transform:uppercase;letter-spacing:1px;color:#6b7280;margin-bottom:5px">Content Repurposer · ${esc(m.sourceType.replace(/_/g,' '))}</div>
    <div style="font-size:18px;font-weight:700">${esc(m.sourceTitle||'Untitled')}</div>
    <div style="font-size:13px;color:#9ca3af;margin-top:4px">${(m.targetFormats||[]).length} formats generated</div>
  </div>
  <div style="background:#f0f9ff;padding:14px 26px;border:1px solid #bae6fd;border-top:none">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#0369a1;margin-bottom:4px">Best angle</div>
    <div style="font-size:14px;color:#1e40af;line-height:1.6">${esc(r.best_performing_angle)}</div>
  </div>
  ${formatBlocks}
  <div style="background:#111827;color:#4b5563;font-size:11px;padding:12px 26px;border-radius:0 0 10px 10px;font-family:monospace;text-align:center">
    Content Repurposer · ${new Date().toLocaleDateString()}
  </div>
</div>
</body></html>`;

return [{ json: { html, replyEmail: m.replyEmail, sourceTitle: m.sourceTitle, formatCount: (m.targetFormats||[]).length, repurposed: r } }];
